const item=$input.first();
const raw=item?.json?.body && item?.json?.headers ? item.json.body : (item?.json ?? {});
const binary=item?.binary?.data;
const requestId=String(raw.requestId ?? ('ocr-' + $execution.id));
const leadId=String(raw.leadId ?? '');
const customerSide=String(raw.customerSide ?? 'left');
const capturedAt=String(raw.capturedAt ?? '');
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const allowedSides=new Set(['left','right']);
const mime=String(binary?.mimeType ?? '').toLowerCase();
const allowedMime=new Set(['image/png','image/jpeg','image/webp']);
const fileSize=Number(binary?.fileSize ?? 0);
const valid=uuid.test(leadId)&&allowedSides.has(customerSide)&&binary&&allowedMime.has(mime)&&(fileSize===0||fileSize<=8*1024*1024);
return [{json:{
  requestId,leadId,customerSide,capturedAt,
  status:valid?'running':'error',
  stage:valid?'ocr':'input',
  startedAt:new Date().toISOString(),
  errorCategory:valid?null:'invalid-input'
},binary:item.binary}];

