const meta=$('เตรียม OCR').item.json;
const ocr=$('Local OCR · PaddleOCR').item.json;
let parsed={};
try {
  const content=$json?.message?.content;
  parsed=typeof content==='string'?JSON.parse(content):($json??{});
} catch {}
const lines=Array.isArray(ocr.lines)?ocr.lines:[];
const byIndex=new Map(lines.map(x=>[Number(x.index),x]));
const seen=new Set();
const messages=[];
let invalid=false;
for(const group of Array.isArray(parsed.groups)?parsed.groups:[]){
  const indexes=Array.isArray(group.lineIndexes)?group.lineIndexes.map(Number):[];
  if(!indexes.length){invalid=true;continue;}
  const picked=[];
  for(const index of indexes){
    if(seen.has(index)||!byIndex.has(index)){invalid=true;continue;}
    seen.add(index);picked.push(byIndex.get(index));
  }
  if(!picked.length) continue;
  const exact=picked.map(x=>String(x.text)).join('\n').trim();
  if(String(group.text??'').trim()!==exact) invalid=true;
  const sideCounts=picked.reduce((acc,x)=>{acc[x.side]=(acc[x.side]||0)+1;return acc;},{});
  const side=Object.entries(sideCounts).sort((a,b)=>b[1]-a[1])[0]?.[0]??'unknown';
  const direction=side===meta.customerSide?'inbound':(side==='left'||side==='right'?'outbound':'unknown');
  const confidence=picked.reduce((sum,x)=>sum+Number(x.confidence||0),0)/picked.length;
  messages.push({lineIndexes:indexes,text:exact,side,direction,confidence:Number(confidence.toFixed(4))});
}
if(seen.size!==lines.length) invalid=true;
const finishedAt=new Date().toISOString();
return [{json:{
  requestId:meta.requestId,
  leadId:meta.leadId,
  capturedAt:meta.capturedAt||null,
  imageDigestSha256:ocr.imageDigestSha256??null,
  ocrModel:ocr.model??'PP-OCRv5/th-mobile',
  status:invalid?'error':'proposal',
  stage:invalid?'validation':'review',
  reviewRequired:true,
  messages:invalid?[]:messages,
  lineCount:lines.length,
  meanConfidence:Number(ocr.meanConfidence??0),
  lowConfidenceLineCount:Number(ocr.lowConfidenceLineCount??0),
  startedAt:meta.startedAt,
  finishedAt,
  elapsedMs:Math.max(0,Date.parse(finishedAt)-Date.parse(meta.startedAt)),
  errorCategory:invalid?'local-grouping-invalid':null
}}];

const data=$json;
const finishedAt=new Date().toISOString();
return [{json:{
  requestId:data.requestId??('ocr-' + $execution.id),
  leadId:data.leadId??null,
  status:'error',
  stage:data.stage??'input',
  reviewRequired:true,
  messages:[],
  errorCategory:data.errorCategory??'chat-ocr-failed',
  startedAt:data.startedAt??finishedAt,
  finishedAt,
  elapsedMs:Math.max(0,Date.parse(finishedAt)-Date.parse(data.startedAt??finishedAt))
}}];
